import itertools

def solve(n):
    subsets = []
    for i in range(1 << n):
        subset = []
        for j in range(n):
            if (i >> j) & 1:
                subset.append(j)
        subsets.append(tuple(subset))

    # Map each subset to its index
    subset_to_idx = {s: i for i, s in enumerate(subsets)}

    # Precompute unions and intersections
    unions = {}
    intersections = {}
    for s1 in subsets:
        for s2 in subsets:
            u = tuple(sorted(set(s1) | set(s2)))
            i = tuple(sorted(set(s1) & set(s2)))
            unions[(s1, s2)] = subset_to_idx[u]
            intersections[(s1, s2)] = subset_to_idx[i]

    count = 0
    # Iterate over all possible colorings (2**(2**n))
    for coloring in itertools.product([0, 1], repeat=1 << n):
        # coloring[i] = 1 if subset i is blue, 0 if green

        # Precompute f(T) for all T
        f = [0] * (1 << n)
        for t_idx in range(1 << n):
            t = subsets[t_idx]
            # Number of subsets of T that are blue
            # A subset X of T is a subset of S such that X \subseteq T
            # X is a subset of T if (index of X) & (index of T) == (index of X)
            count_blue = 0
            for x_idx in range(1 << n):
                if (x_idx & t_idx) == x_idx:
                    if coloring[x_idx] == 1:
                        count_blue += 1
            f[t_idx] = count_blue

        # Check condition
        possible = True
        for s1_idx in range(1 << n):
            for s2_idx in range(1 << n):
                s1 = subsets[s1_idx]
                s2 = subsets[s2_idx]
                if f[s1_idx] * f[s2_idx] != f[unions[(s1, s2)]] * f[intersections[(s1, s2)]]:
                    possible = False
                    break
            if not possible:
                break
        if possible:
            count += 1

    return count

