import itertools

def solve(n):
    # Use a more efficient way to check
    # f(T) is determined by the coloring
    # The condition f(T1)f(T2) = f(T1 U T2)f(T1 \cap T2)
    # This is a very strong condition.
    # Let's use a more optimized search.

    count = 0
    # There are 2^(2^n) colorings. For n=4, this is 2^16 = 65536.
    # This is small enough.

    for coloring_int in range(1 << (1 << n)):
        coloring = [(coloring_int >> i) & 1 for i in range(1 << n)]

        f = [0] * (1 << n)
        for t_idx in range(1 << n):
            # Count bits set in (x_idx & t_idx) == x_idx
            # This is just iterating over subsets of t_idx
            # A common way to iterate over subsets:
            s = t_idx
            while True:
                if coloring[s]:
                    f[t_idx] += 1
                if s == 0:
                    break
                s = (s - 1) & t_idx

        possible = True
        # Only need to check for T1, T2 such that T1 is not a subset of T2 and vice versa
        for t1 in range(1 << n):
            for t2 in range(t1 + 1, 1 << n):
                if (t1 & t2) == t1 or (t1 & t2) == t2:
                    continue
                if f[t1] * f[t2] != f[t1 | t2] * f[t1 & t2]:
                    possible = False
                    break
            if not possible:
                break
        if possible:
            count += 1
    return count

