import itertools

def get_colorings(n):
    subsets = []
    for i in range(1 << n):
        subset = []
        for j in range(n):
            if (i >> j) & 1:
                subset.append(j)
        subsets.append(tuple(subset))

    subset_to_idx = {s: i for i, s in enumerate(subsets)}

    unions = {}
    intersections = {}
    for s1 in subsets:
        for s2 in subsets:
            u = tuple(sorted(set(s1) | set(s2)))
            i = tuple(sorted(set(s1) & set(s2)))
            unions[(s1, s2)] = subset_to_idx[u]
            intersections[(s1, s2)] = subset_to_idx[i]

    valid_colorings = []
    for coloring_int in range(1 << (1 << n)):
        coloring = [(coloring_int >> i) & 1 for i in range(1 << n)]
        f = [0] * (1 << n)
        for t_idx in range(1 << n):
            count_blue = 0
            for x_idx in range(1 << n):
                if (x_idx & t_idx) == x_idx:
                    if coloring[x_idx]:
                        count_blue += 1
            f[t_idx] = count_blue

        possible = True
        for s1_idx in range(1 << n):
            for s2_idx in range(s1_idx + 1, 1 << n):
                if f[s1_idx] * f[s2_idx] != f[unions[(subsets[s1_idx], subsets[s2_idx])]] * f[intersections[(subsets[s1_idx], subsets[s2_idx])]]:
                    possible = False
                    break
            if not possible:
                break
        if possible:
            valid_colorings.append(coloring)

    return valid_colorings

